class Container {
public:
    Container() {}
    Container(const Container&) { /* Costly Copy */ }
    // C++17 Mandatory: RVO/NRVO preferred over move
};

// Named Return Value Optimization (NRVO)
Container build_named() {
    Container c;
    return c; // NRVO attempts to construct 'c'
              // directly in caller's memory
}

// Return Value Optimization (RVO)
// Guaranteed Copy Elision (C++17+)
Container build_temp() {
    return Container();
}

Container a = build_named();
Container b = build_temp();
